TIME_RE = re.compile(r"is ([0-9.eE+-]+) milli-seconds, estimated TFLOPS is ([0-9.eE+-]+)")


def command(exe, case, max_hints, verify):
    _, _, batch, seqlens, seqlens_kv, max_q, max_kv, alpha, attn_scale = case
    if max_hints == "real":
        max_q = max(int(x) for x in seqlens.split(","))
        max_kv = max(int(x) for x in seqlens_kv.split(","))
    return exe + [
        f"-v={int(verify)}", "-perf=1", "-prec=fp16", "-jagged=1", f"-b={batch}",
        "-nhead=1", "-hdim_qk=128", "-hdim_v=128", "-softmax=1", "-training=0",
        "-causal=0", "-local_len=0", "-context_len=0", "-minfull_len=0",
        f"-alpha={alpha}", f"-attn_scale={attn_scale}",
        f"-max_seqlen={max_q}", f"-max_seqlen_kv={max_kv}",
        f"-seqlens={seqlens}", f"-seqlens_kv={seqlens_kv}",
    ]


def main():
    parser = argparse.ArgumentParser(
        description="Benchmark the HSTU forward on production cross-attention cases.")
    parser.add_argument("--build", default=BUILD, help="CMake build dir (default: build)")
    parser.add_argument("--set", default="all", choices=["igr_lsr_real", "synthetic", "all"])
    parser.add_argument("--max-hints", default="prod", choices=["prod", "real"],
                        help="max_seqlen / max_seqlen_kv: what the model passes, or the real maxima")
    parser.add_argument("--verify", action="store_true", help="also run the CPU validation (-v=1)")
    parser.add_argument("--csv-out", default="", help="write per-case results here")
    parser.add_argument("--dry-run", action="store_true", help="print the commands only")
    args = parser.parse_args()

    exe = [f"{args.build}/bin/tile_example_hstu_attention_fwd"]
    selected = [c for c in CASES if args.set in ("all", c[0])]

    rows, rc = [], 0
    for case in selected:
        cmd = command(exe, case, args.max_hints, args.verify)
        print("+ " + " ".join(cmd), flush=True)
        if args.dry_run:
            continue
        result = subprocess.run(cmd, capture_output=True, text=True)
        out = result.stdout + result.stderr
        m = TIME_RE.search(out)
        if result.returncode != 0 or m is None:
            rc = result.returncode or 1
            print(out, file=sys.stderr)
            print(f"{case[1]}: FAILED (exit {result.returncode})", flush=True)
            continue
        ms, tflops = float(m.group(1)), float(m.group(2))
        rows.append((case[0], case[1], case[2], ms, tflops))
        print(f"{case[1]}: {ms * 1000:.1f} us, {tflops:.1f} TFLOPS", flush=True)

    for name in ("igr_lsr_real", "synthetic"):
        sel = [r for r in rows if r[0] == name]
        if sel:
            total = sum(r[3] for r in sel)
            geo = math.exp(sum(math.log(r[3]) for r in sel) / len(sel))
            print(f"{name}: {len(sel)} cases, total {total:.3f} ms, geomean {geo * 1000:.1f} us")

    if args.csv_out and rows:
        with open(args.csv_out, "w", newline="") as f:
            w = csv.writer(f)
            w.writerow(["set", "case", "batch", "ms", "tflops"])
            w.writerows(rows)
        print(f"wrote {args.csv_out}")
    return rc


if __name__ == "__main__":
    sys.exit(main())

